import java.io.BufferedInputStream;
import java.io.IOException;

public class Main {
    private static final class FastScanner {
        private final BufferedInputStream in = new BufferedInputStream(System.in);
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long value = 0;
            while (c > ' ') {
                value = value * 10 + (c - '0');
                c = read();
            }
            return value * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        long[] x = new long[7];
        long[] y = new long[7];

        for (int i = 0; i < 7; i++) {
            x[i] = fs.nextLong();
            y[i] = fs.nextLong();
        }

        // ∠P2P1P3 must be acute, and P1P2 = P1P3.
        long ax = x[1] - x[0], ay = y[1] - y[0];
        long bx = x[2] - x[0], by = y[2] - y[0];
        boolean valid = ax * bx + ay * by > 0
                && ax * ax + ay * ay == bx * bx + by * by;

        // P2, P3, P4, P5 must be collinear.
        long dx = x[2] - x[1], dy = y[2] - y[1];
        long cross4 = dx * (y[3] - y[1]) - dy * (x[3] - x[1]);
        long cross5 = dx * (y[4] - y[1]) - dy * (x[4] - x[1]);
        valid &= cross4 == 0 && cross5 == 0;

        // The midpoints of P2P3 and P4P5 must coincide.
        valid &= x[1] + x[2] == x[3] + x[4]
                && y[1] + y[2] == y[3] + y[4];

        // P2P3 must be longer than P4P5.
        long baseLengthSquared = dx * dx + dy * dy;
        long smallerLengthSquared = (x[4] - x[3]) * (x[4] - x[3])
                + (y[4] - y[3]) * (y[4] - y[3]);
        valid &= baseLengthSquared > smallerLengthSquared;

        // P4P6 and P5P7 must be perpendicular to P2P3 and have equal lengths.
        long p46x = x[5] - x[3], p46y = y[5] - y[3];
        long p57x = x[6] - x[4], p57y = y[6] - y[4];
        valid &= dx * p46x + dy * p46y == 0
                && dx * p57x + dy * p57y == 0
                && p46x * p46x + p46y * p46y == p57x * p57x + p57y * p57y;

        // P1 and P6 must lie strictly on opposite sides of the line P2P3.
        long side1 = dx * (y[0] - y[1]) - dy * (x[0] - x[1]);
        long side6 = dx * (y[5] - y[1]) - dy * (x[5] - x[1]);
        valid &= (side1 < 0 && side6 > 0) || (side1 > 0 && side6 < 0);

        System.out.println(valid ? "S" : "N");
    }
}
```

